// Se usa graphicsLayer + drawBehind ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â la Paint se crea una sola vez por key de color/radius
fun Modifier.coloredShadow(
    color: Color,
    borderRadius: Dp = 16.dp,
    blurRadius: Dp = 32.dp,
    offsetY: Dp = 12.dp,
    shadowAlpha: Float = 0.7f
): Modifier = this.graphicsLayer {
    shape = RoundedCornerShape(borderRadius)
    clip = false
    shadowElevation = blurRadius.toPx() * 0.55f
    ambientShadowColor = color.copy(alpha = shadowAlpha * 0.7f)
