// FIX: Palette.generate callback se ejecuta en hilo desconocido; usamos
//      withContext(Dispatchers.IO) + suspendCoroutine para obtener el color
//      en coroutine y actualizar el state de forma segura en el hilo principal.
@Composable
fun rememberDominantColor(uri: Uri?): Color {
    val context = LocalContext.current
    var dominantColor by remember { mutableStateOf(Color.Transparent) }

    LaunchedEffect(uri) {
        if (uri == null) {
            dominantColor = Color.Transparent
            return@LaunchedEffect
        }
        val color = withContext(Dispatchers.IO) {
            try {
                val request = ImageRequest.Builder(context)
                    .data(uri)
                    .size(64)           // reducido: 64px suficiente para Palette
                    .allowHardware(false)
                    .build()
                val result = context.imageLoader.execute(request)
                if (result is SuccessResult) {
                    val bitmap = result.drawable.toBitmap()
                    // generateAsync devuelve en el hilo llamante (IO)
                    val palette = Palette.Builder(bitmap).maximumColorCount(8).generate()
                    val argb = palette.vibrantSwatch?.rgb
                        ?: palette.dominantSwatch?.rgb
                        ?: palette.mutedSwatch?.rgb
                    argb?.let { Color(it) }
                } else null
            } catch (_: Exception) { null }
        }
        // ActualizaciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n en Main (garantizado por LaunchedEffect)
        if (color != null) dominantColor = color
    }

    return dominantColor
}

