// FIX: memoizado con remember para no recalcular cada recomposiciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n
@Composable
private fun Color.rememberAdaptedForTheme(isDark: Boolean): Color {
    return remember(this, isDark) {
        val lum = luminance()
        when {
            isDark  && lum < 0.2f  -> lerpColor(this, Color.White, 0.35f)
            !isDark && lum > 0.75f -> lerpColor(this, Color.Black, 0.35f)
            else -> this
        }
    }
}

@Composable
fun AlbumDetailScreen(
    albumId: Long,
    viewModel: LibraryViewModel,
    onAlbumClick: (Long) -> Unit = {},
    onArtistClick: (Long) -> Unit = {},
    onBack: () -> Unit = {},
    onPlaySong: (com.soundly.data.model.Song, List<com.soundly.data.model.Song>) -> Unit = { _, _ -> },
    onPlayCollection: (List<com.soundly.data.model.Song>, Boolean) -> Unit = { _, _ -> }
) {
    val playbackViewModel: PlaybackViewModel = hiltViewModel()
    val songs   = viewModel.getSongsForAlbum(albumId).collectAsState(initial = emptyList()).value
    val albums  = viewModel.albums.collectAsState().value
    val album   = remember(albums, albumId) { albums.find { it.id == albumId } }
    val artists = viewModel.artists.collectAsState().value
    val favoriteAlbumIds = viewModel.favoriteAlbumIds.collectAsState().value
    val favoriteSongIds = viewModel.favoriteSongIds.collectAsState().value
    val userPlaylists = viewModel.userPlaylists.collectAsState().value
    val playlistMembershipBySong = viewModel.playlistMembershipBySong.collectAsState().value
    val artist  = remember(artists, album?.artist) { artists.find { it.name == album?.artist } }
    val isFavorite = albumId in favoriteAlbumIds
    val artistArtUri = remember(artist?.id) {
        artist?.let { viewModel.getArtistArtUri(it.id) }
    }

    // FIX: artUri derivado con remember para no recalcular en cada recomposiciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n
    val artUri = remember(album?.id) { album?.let { viewModel.getAlbumArtUri(it.id) } }

    val listState   = rememberLazyListState()
    val density     = LocalDensity.current
