            //      Evita que drawBehind recree la Paint cada frame de animaciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n
            val effectiveShadowAlpha = shadowAlpha * 0.8f
            val shadowModifier = remember(dominantColor, effectiveShadowAlpha, hasColor) {
                if (hasColor && effectiveShadowAlpha > 0.01f)
                    Modifier.coloredShadow(
                        color        = dominantColor,
                        borderRadius = 16.dp,   // usamos el valor expandido; el clip ya redondea
                        blurRadius   = 28.dp,
                        offsetY      = 11.dp,
                        shadowAlpha  = effectiveShadowAlpha
                    )
                else Modifier
            }

            AsyncImage(
                model = ImageRequest.Builder(LocalContext.current)
                    .data(viewModel.getAlbumArtUri(it.id))
                    .crossfade(false)
                    .build(),
                placeholder        = painterResource(R.drawable.carga),
                error              = painterResource(R.drawable.carga),
                contentDescription = "Carátula",
                modifier = Modifier
                    .padding(start = artStart, top = artTop)
                    .size(artSize)
                    .then(shadowModifier)
                    .clip(RoundedCornerShape(cornerRad)),
                contentScale = ContentScale.Crop
            )
        }

