                        Icon(
                            imageVector        = if (isFavorite) Icons.Default.CheckCircle else Icons.Default.AddCircleOutline,
                            contentDescription = if (isFavorite) "Añadido a la biblioteca" else "Añadir a la biblioteca",
                            tint               = MaterialTheme.colorScheme.onBackground
                        )
                    }
                    IconButton(onClick = { }) {
                        Icon(
                            imageVector        = Icons.Default.MoreHoriz,
                            contentDescription = "Más opciones",
                            tint               = MaterialTheme.colorScheme.onBackground
                        )
                    }
                }

                Spacer(Modifier.weight(1f))

                Row(verticalAlignment = Alignment.CenterVertically) {
                    Row(
                        modifier = Modifier
                            .clip(RoundedCornerShape(50))
                            .background(shuffleColor.copy(alpha = 0.15f))
                            .clickable(enabled = songs.isNotEmpty()) { onPlayCollection(songs, true) }
                            .padding(horizontal = 16.dp, vertical = 16.dp),
                        verticalAlignment     = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.Center
                    ) {
                        Icon(
                            imageVector        = Icons.Default.Shuffle,
                            contentDescription = null,
                            tint               = shuffleColor,
                            modifier           = Modifier.size(18.dp)
                        )
                        Spacer(Modifier.width(8.dp))
                        Text(
                            text       = "Aleatorio",
                            color      = shuffleColor,
                            fontWeight = FontWeight.Bold,
                            style      = MaterialTheme.typography.bodyMedium
                        )
                    }

                    Spacer(Modifier.width(10.dp))

                    @OptIn(ExperimentalMaterial3ExpressiveApi::class)
                    val cookieShape = MaterialShapes.Cookie6Sided.toShape()

                    FloatingActionButton(
                        onClick        = {
                            if (songs.isNotEmpty()) {
                                onPlayCollection(songs, false)
                            }
                        },
                        shape          = cookieShape,
                        containerColor = MaterialTheme.colorScheme.primary,
                        contentColor   = MaterialTheme.colorScheme.onPrimary
                    ) {
                        Icon(Icons.Default.PlayArrow, contentDescription = null)
                    }
                }
            }
        }
    }
}



@Composable
fun AlbumDetailScreen(
    playlist: com.soundly.data.model.Playlist,
    songs: List<com.soundly.data.model.Song>,
    ownerName: String,
    viewModel: LibraryViewModel,
    ownerImageUri: Uri?,
    albumArtProvider: (Long) -> Uri,
    onAlbumClick: (Long) -> Unit = {},
    onArtistClick: (Long) -> Unit = {},
    onBack: () -> Unit = {},
    onPlaySong: (com.soundly.data.model.Song, List<com.soundly.data.model.Song>) -> Unit = { _, _ -> },
    onPlayCollection: (List<com.soundly.data.model.Song>, Boolean) -> Unit = { _, _ -> }
) {
    val context = LocalContext.current
    val playbackViewModel: PlaybackViewModel = hiltViewModel()
    val density = LocalDensity.current
    val screenWidth = with(density) { LocalWindowInfo.current.containerSize.width.toDp() }
    val coverModel = remember(playlist.id, playlist.artworkUri, playlist.isAutoGenerated) {
        if (playlist.isAutoGenerated) {
            R.drawable.playlist_favicon
        } else {
            playlist.artworkUri ?: R.drawable.playlist_favicon
        }
    }
    val accentUri = remember(playlist.id, playlist.artworkUri, songs.firstOrNull()?.albumId) {
        playlist.artworkUri ?: songs.firstOrNull()?.let { albumArtProvider(it.albumId) }
    }
    val ownerArtworkModel = remember(playlist.id, ownerImageUri, playlist.isAutoGenerated) {
        if (playlist.isAutoGenerated) R.drawable.logo_soundly else ownerImageUri ?: R.drawable.playlist_favicon
    }
    val playlistOwnerName = if (playlist.isAutoGenerated) "Soundly" else ownerName.ifBlank { "Tu perfil" }
    val playlistMeta = remember(playlist.isAutoGenerated, songs.size) {
        buildString {
            append(if (playlist.isAutoGenerated) "Playlist autogenerada" else "Playlist")
            append(" • ")
            append(if (songs.size == 1) "1 canción" else "${songs.size} canciones")
        }
    }

    val favoriteSongIds = viewModel.favoriteSongIds.collectAsState().value
    val userPlaylists = viewModel.userPlaylists.collectAsState().value
    val playlistMembershipBySong = viewModel.playlistMembershipBySong.collectAsState().value

    val listState = rememberLazyListState()
    val rawColor = rememberDominantColor(uri = accentUri)
    val dominantColor by animateColorAsState(
        targetValue = rawColor,
        animationSpec = SPRING_COLOR_SLOW,
        label = "playlistDominantColor"
    )
    val hasColor = dominantColor != Color.Transparent
    val isDark = MaterialTheme.colorScheme.surface.luminance() < 0.5f
    val adaptedDominantColor = dominantColor.rememberAdaptedForTheme(isDark)
    val actionColor = if (hasColor) adaptedDominantColor else MaterialTheme.colorScheme.onSurfaceVariant

    val rawOffset by remember {
        derivedStateOf {
            if (listState.firstVisibleItemIndex > 0) SCROLL_ART_RANGE
            else listState.firstVisibleItemScrollOffset.toFloat()
        }
    }
    val artProgress by remember {
        derivedStateOf { (rawOffset / SCROLL_ART_RANGE).coerceIn(0f, 1f) }
    }
    val hdrProgress by remember {
        derivedStateOf { ((rawOffset - SCROLL_HDR_START) / SCROLL_HDR_RANGE).coerceIn(0f, 1f) }
    }

    val artSizeTarget = lerp(ART_EXPANDED, ART_COLLAPSED, artProgress)
    val artTopTarget = lerp(HEADER_HEIGHT + 4.dp, 20.dp, artProgress)
    val artStartTarget = lerp((screenWidth - ART_EXPANDED) / 2, 56.dp, artProgress)
    val cornerTarget = lerp(16.dp, 8.dp, artProgress)

    val artSize by animateDpAsState(artSizeTarget, SPRING_DP_MEDIUM, label = "playlistArtSize")
    val artTop by animateDpAsState(artTopTarget, SPRING_DP_MEDIUM, label = "playlistArtTop")
    val artStart by animateDpAsState(artStartTarget, SPRING_DP_MEDIUM, label = "playlistArtStart")
    val cornerRad by animateDpAsState(cornerTarget, SPRING_DP_MEDIUM, label = "playlistCornerRad")

    var actionBarYPx by remember { mutableFloatStateOf(Float.MAX_VALUE) }
    val headerHeightPx = with(density) { HEADER_HEIGHT.toPx() }
    val fadeZonePx = with(density) { 40.dp.toPx() }
    val stickyAlpha by remember {
        derivedStateOf {
            val dist = actionBarYPx - headerHeightPx
            ((1f - dist / fadeZonePx)).coerceIn(0f, 1f)
        }
    }
    val isSticky by remember {
        derivedStateOf { stickyAlpha > 0f }
    }

    var overscrollPx by remember { mutableFloatStateOf(0f) }
    val maxOverscrollPx = with(density) { 120.dp.toPx() }
    val elasticNestedScroll = remember {
        object : NestedScrollConnection {
            override fun onPreScroll(available: Offset, source: NestedScrollSource): Offset {
                return if (overscrollPx > 0f && available.y < 0f) {
                    val consumed = available.y.coerceAtLeast(-overscrollPx)
                    overscrollPx = (overscrollPx + consumed).coerceAtLeast(0f)
                    Offset(0f, consumed)
                } else Offset.Zero
            }

            override fun onPostScroll(consumed: Offset, available: Offset, source: NestedScrollSource): Offset {
                return if (available.y > 0f && source == NestedScrollSource.UserInput) {
                    val extra = available.y * 0.4f
                    overscrollPx = (overscrollPx + extra).coerceIn(0f, maxOverscrollPx)
                    Offset(0f, available.y)
                } else Offset.Zero
            }

            override suspend fun onPostFling(consumed: Velocity, available: Velocity): Velocity {
                androidx.compose.animation.core.animate(
                    initialValue = overscrollPx,
                    targetValue = 0f,
                    animationSpec = spring(
                        dampingRatio = Spring.DampingRatioMediumBouncy,
                        stiffness = Spring.StiffnessMediumLow
                    )
                ) { value, _ -> overscrollPx = value }
                return Velocity.Zero
            }
        }
    }

    val bigAlpha by animateFloatAsState((1f - artProgress * 2.5f).coerceIn(0f, 1f), SPRING_FLOAT_MEDIUM, label = "playlistBigAlpha")
    val smallAlpha by animateFloatAsState((hdrProgress * 2f).coerceIn(0f, 1f), SPRING_FLOAT_MEDIUM, label = "playlistSmallAlpha")
    val hdrAlpha by animateFloatAsState(hdrProgress, SPRING_FLOAT_MEDIUM, label = "playlistHdrAlpha")
    val shadowAlpha by animateFloatAsState((1f - artProgress * 1.5f).coerceIn(0f, 1f), SPRING_FLOAT_MEDIUM, label = "playlistShadowAlpha")

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background)
            .nestedScroll(elasticNestedScroll)
            .graphicsLayer { translationY = overscrollPx }
    ) {
        LazyColumn(
            state = listState,
            modifier = Modifier.fillMaxSize(),
            contentPadding = PaddingValues(
                top = HEADER_HEIGHT + ART_EXPANDED + 12.dp,
                bottom = 32.dp
            )
        ) {
            item(key = "playlist_header_info") {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 20.dp)
                        .padding(top = 16.dp, bottom = 4.dp)
                        .alpha(bigAlpha)
                ) {
                    Text(
                        text = playlist.name,
                        style = MaterialTheme.typography.titleLarge,
                        color = MaterialTheme.colorScheme.onBackground,
                        fontWeight = FontWeight.Bold,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis
                    )
                    Spacer(Modifier.height(4.dp))
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        AsyncImage(
                            model = ownerArtworkModel,
                            placeholder = painterResource(R.drawable.playlist_favicon),
                            error = painterResource(R.drawable.playlist_favicon),
                            contentDescription = null,
                            modifier = Modifier
                                .size(25.dp)
                                .clip(CircleShape),
                            contentScale = ContentScale.Crop
                        )
                        Spacer(Modifier.width(12.dp))
                        Text(
                            text = playlistOwnerName,
                            style = MaterialTheme.typography.labelLarge,
                            color = MaterialTheme.colorScheme.onBackground,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                    Spacer(Modifier.height(4.dp))
                    Text(
                        text = playlistMeta,
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
            }

            item(key = "playlist_action_buttons") {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 20.dp, vertical = 12.dp)
                        .alpha(1f - stickyAlpha)
                        .onGloballyPositioned { coords ->
                            actionBarYPx = coords.positionInRoot().y
                        },
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    IconButton(onClick = { }) {
                        Icon(
                            imageVector = Icons.Default.MoreHoriz,
                            contentDescription = "Más opciones",
                            tint = MaterialTheme.colorScheme.onBackground
                        )
                    }

                    Spacer(Modifier.weight(1f))

                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Row(
                            modifier = Modifier
                                .clip(RoundedCornerShape(50))
                                .background(actionColor.copy(alpha = 0.15f))
                                .clickable(enabled = songs.isNotEmpty()) { onPlayCollection(songs, true) }
                                .padding(horizontal = 16.dp, vertical = 16.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.Center
                        ) {
                            Icon(
                                imageVector = Icons.Default.Shuffle,
                                contentDescription = null,
                                tint = actionColor,
                                modifier = Modifier.size(18.dp)
                            )
                            Spacer(Modifier.width(8.dp))
                            Text(
                                text = "Aleatorio",
                                color = actionColor,
                                fontWeight = FontWeight.Bold,
                                style = MaterialTheme.typography.bodyMedium
                            )
                        }

                        Spacer(Modifier.width(10.dp))

                        @OptIn(ExperimentalMaterial3ExpressiveApi::class)
                        val cookieShape = MaterialShapes.Cookie6Sided.toShape()

                        FloatingActionButton(
                            onClick = {
                                if (songs.isNotEmpty()) {
                                    onPlayCollection(songs, false)
                                }
                            },
                            shape = cookieShape,
                            containerColor = MaterialTheme.colorScheme.primary,
                            contentColor = MaterialTheme.colorScheme.onPrimary
                        ) {
                            Icon(Icons.Default.PlayArrow, contentDescription = null)
                        }
                    }
                }
            }

            if (songs.isEmpty()) {
                item(key = "playlist_empty") {
                    Text(
                        text = if (playlist.isAutoGenerated) {
                            "Tus próximas canciones con like aparecerán aquí automáticamente"
                        } else {
                            "Esta playlist aún no tiene canciones"
                        },
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        modifier = Modifier.padding(horizontal = 20.dp, vertical = 12.dp)
                    )
                }
            } else {
                itemsIndexed(
                    items = songs,
                    key = { _, song -> song.id },
                    contentType = { _, _ -> "playlist_song" }
                ) { index, song ->
                    val cancion = remember(song.id, song.title, song.artist, song.albumId) {
                        Cancion(
                            caratulaUri = albumArtProvider(song.albumId),
                            titulo = song.title,
                            artista = song.artist
                        )
                    }
                    ItemCancionAlbum(
                        cancion = cancion,
                        trackNumber = index + 1,
                        onClick = { onPlaySong(song, songs) },
                        menuContent = {
                            SongOverflowMenuButton(
                                song = song,
                                source = SongMenuSource.Playlist(
                                    playlistId = playlist.id,
                                    isAutoGenerated = playlist.isAutoGenerated
                                ),
                                userPlaylists = userPlaylists,
                                playlistIdsContainingSong = playlistMembershipBySong[song.id].orEmpty(),
                                isFavorite = song.id in favoriteSongIds,
                                onPlayNext = { playbackViewModel.playNext(song) },
                                onAddToQueue = { playbackViewModel.addToQueue(song) },
                                onOpenAlbum = onAlbumClick,
                                onOpenArtist = onArtistClick,
                                onAddToPlaylist = { playlistId ->
                                    viewModel.addSongToPlaylist(playlistId, song.id)
                                },
                                onAddToFavorites = {
                                    viewModel.toggleSongFavorite(song.id)
                                },
                                onDeleteSong = {
                                    viewModel.removeSongFromPlaylist(playlist.id, song.id)
                                }
                            )
                        }
                    )
                }
            }
        }

        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(HEADER_HEIGHT)
                .align(Alignment.TopCenter)
                .background(MaterialTheme.colorScheme.background.copy(alpha = hdrAlpha))
                .padding(horizontal = 4.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = onBack) {
                Icon(
                    imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                    contentDescription = "Volver",
                    tint = MaterialTheme.colorScheme.onBackground
                )
            }
            Spacer(Modifier.width(60.dp))
            Column(
                modifier = Modifier
                    .weight(1f)
                    .alpha(smallAlpha)
            ) {
                Text(
                    text = playlist.name,
                    style = MaterialTheme.typography.titleMedium,
                    color = MaterialTheme.colorScheme.onBackground,
                    fontWeight = FontWeight.Bold,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
                Text(
                    text = playlistOwnerName,
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
        }

        val effectiveShadowAlpha = shadowAlpha * 0.8f
        val shadowModifier = remember(dominantColor, effectiveShadowAlpha, hasColor) {
            if (hasColor && effectiveShadowAlpha > 0.01f) {
                Modifier.coloredShadow(
                    color = dominantColor,
                    borderRadius = 16.dp,
                    blurRadius = 28.dp,
                    offsetY = 11.dp,
                    shadowAlpha = effectiveShadowAlpha
                )
            } else Modifier
        }

        AsyncImage(
            model = ImageRequest.Builder(context)
                .data(coverModel)
                .crossfade(false)
                .build(),
            placeholder = painterResource(R.drawable.playlist_favicon),
            error = painterResource(R.drawable.playlist_favicon),
            contentDescription = "Portada",
            modifier = Modifier
                .padding(start = artStart, top = artTop)
                .size(artSize)
                .then(shadowModifier)
                .clip(RoundedCornerShape(cornerRad)),
            contentScale = ContentScale.Crop
        )

        if (isSticky) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = HEADER_HEIGHT)
                    .background(
                        brush = Brush.verticalGradient(
                            colors = listOf(
                                MaterialTheme.colorScheme.background,
                                MaterialTheme.colorScheme.background.copy(alpha = 0f)
                            ),
                            startY = 0f,
                            endY = with(density) { 80.dp.toPx() }
                        )
                    )
                    .padding(horizontal = 20.dp, vertical = 12.dp)
                    .align(Alignment.TopCenter),
                verticalAlignment = Alignment.CenterVertically
            ) {
                IconButton(onClick = { }) {
                    Icon(
                        imageVector = Icons.Default.MoreHoriz,
                        contentDescription = "Más opciones",
                        tint = MaterialTheme.colorScheme.onBackground
                    )
                }

                Spacer(Modifier.weight(1f))

                Row(verticalAlignment = Alignment.CenterVertically) {
                    Row(
                        modifier = Modifier
                            .clip(RoundedCornerShape(50))
                            .background(actionColor.copy(alpha = 0.15f))
                            .clickable(enabled = songs.isNotEmpty()) { onPlayCollection(songs, true) }
                            .padding(horizontal = 16.dp, vertical = 16.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.Shuffle,
                            contentDescription = null,
                            tint = actionColor,
                            modifier = Modifier.size(18.dp)
                        )
                        Spacer(Modifier.width(8.dp))
                        Text(
                            text = "Aleatorio",
                            color = actionColor,
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.bodyMedium
                        )
                    }

                    Spacer(Modifier.width(10.dp))

                    @OptIn(ExperimentalMaterial3ExpressiveApi::class)
                    val cookieShape = MaterialShapes.Cookie6Sided.toShape()

                    FloatingActionButton(
                        onClick = {
                            if (songs.isNotEmpty()) {
                                onPlayCollection(songs, false)
                            }
                        },
                        shape = cookieShape,
                        containerColor = MaterialTheme.colorScheme.primary,
                        contentColor = MaterialTheme.colorScheme.onPrimary
                    ) {
                        Icon(Icons.Default.PlayArrow, contentDescription = null)
                    }
                }
            }
        }
    }
}


@Composable
fun AlbumDetailScreen(
    folderPath: String,
    viewModel: BibliotecaViewModel,
    libraryViewModel: LibraryViewModel,
    onAlbumClick: (Long) -> Unit = {},
    onArtistClick: (Long) -> Unit = {},
    onBack: () -> Unit = {},
    onPlaySong: (com.soundly.data.model.Song, List<com.soundly.data.model.Song>) -> Unit = { _, _ -> },
    onPlayCollection: (List<com.soundly.data.model.Song>, Boolean) -> Unit = { _, _ -> }
) {
    val context = LocalContext.current
    val playbackViewModel: PlaybackViewModel = hiltViewModel()
    val density = LocalDensity.current
    val screenWidth = with(density) { LocalWindowInfo.current.containerSize.width.toDp() }

    val songs by viewModel.getSongsForFolder(folderPath).collectAsState(initial = emptyList())
    val folderName = folderPath.substringAfterLast("/")
    val playlistMeta = if (songs.size == 1) "1 canción" else "${songs.size} canciones"

    val favoriteFolderPaths by viewModel.favoriteFolderPaths.collectAsState()
    val isFavoriteFolder = folderPath in favoriteFolderPaths

    val favoriteSongIds = libraryViewModel.favoriteSongIds.collectAsState().value
    val userPlaylists = libraryViewModel.userPlaylists.collectAsState().value
    val playlistMembershipBySong = libraryViewModel.playlistMembershipBySong.collectAsState().value

    val accentUri = remember(songs) {
        songs.firstOrNull()?.let { libraryViewModel.getAlbumArtUri(it.albumId) }
    }

    val listState = rememberLazyListState()
    val rawColor = rememberDominantColor(uri = accentUri)
    val dominantColor by animateColorAsState(
        targetValue = rawColor,
        animationSpec = SPRING_COLOR_SLOW,
        label = "folderDominantColor"
    )
    val hasColor = dominantColor != Color.Transparent
    val isDark = MaterialTheme.colorScheme.surface.luminance() < 0.5f
    val adaptedDominantColor = dominantColor.rememberAdaptedForTheme(isDark)
    val actionColor = if (hasColor) adaptedDominantColor else MaterialTheme.colorScheme.onSurfaceVariant

    val rawOffset by remember {
        derivedStateOf {
            if (listState.firstVisibleItemIndex > 0) SCROLL_ART_RANGE
            else listState.firstVisibleItemScrollOffset.toFloat()
        }
    }
    val artProgress by remember {
        derivedStateOf { (rawOffset / SCROLL_ART_RANGE).coerceIn(0f, 1f) }
    }
    val hdrProgress by remember {
        derivedStateOf { ((rawOffset - SCROLL_HDR_START) / SCROLL_HDR_RANGE).coerceIn(0f, 1f) }
    }

    val artSizeTarget = lerp(ART_EXPANDED, ART_COLLAPSED, artProgress)
    val artTopTarget = lerp(HEADER_HEIGHT + 4.dp, 20.dp, artProgress)
    val artStartTarget = lerp((screenWidth - ART_EXPANDED) / 2, 56.dp, artProgress)
    val cornerTarget = lerp(16.dp, 8.dp, artProgress)

    val artSize by animateDpAsState(artSizeTarget, SPRING_DP_MEDIUM, label = "folderArtSize")
    val artTop by animateDpAsState(artTopTarget, SPRING_DP_MEDIUM, label = "folderArtTop")
    val artStart by animateDpAsState(artStartTarget, SPRING_DP_MEDIUM, label = "folderArtStart")
    val cornerRad by animateDpAsState(cornerTarget, SPRING_DP_MEDIUM, label = "folderCornerRad")

    var actionBarYPx by remember { mutableFloatStateOf(Float.MAX_VALUE) }
    val headerHeightPx = with(density) { HEADER_HEIGHT.toPx() }
    val fadeZonePx = with(density) { 40.dp.toPx() }
    val stickyAlpha by remember {
        derivedStateOf {
            val dist = actionBarYPx - headerHeightPx
            ((1f - dist / fadeZonePx)).coerceIn(0f, 1f)
        }
    }
    val isSticky by remember {
        derivedStateOf { stickyAlpha > 0f }
    }

    var overscrollPx by remember { mutableFloatStateOf(0f) }
    val maxOverscrollPx = with(density) { 120.dp.toPx() }
    val elasticNestedScroll = remember {
        object : NestedScrollConnection {
            override fun onPreScroll(available: Offset, source: NestedScrollSource): Offset {
                return if (overscrollPx > 0f && available.y < 0f) {
                    val consumed = available.y.coerceAtLeast(-overscrollPx)
                    overscrollPx = (overscrollPx + consumed).coerceAtLeast(0f)
                    Offset(0f, consumed)
                } else Offset.Zero
            }

            override fun onPostScroll(consumed: Offset, available: Offset, source: NestedScrollSource): Offset {
                return if (available.y > 0f && source == NestedScrollSource.UserInput) {
                    val extra = available.y * 0.4f
                    overscrollPx = (overscrollPx + extra).coerceIn(0f, maxOverscrollPx)
                    Offset(0f, available.y)
                } else Offset.Zero
            }

            override suspend fun onPostFling(consumed: Velocity, available: Velocity): Velocity {
                androidx.compose.animation.core.animate(
                    initialValue = overscrollPx,
                    targetValue = 0f,
                    animationSpec = spring(
                        dampingRatio = Spring.DampingRatioMediumBouncy,
                        stiffness = Spring.StiffnessMediumLow
                    )
                ) { value, _ -> overscrollPx = value }
                return Velocity.Zero
            }
        }
    }

    val bigAlpha by animateFloatAsState((1f - artProgress * 2.5f).coerceIn(0f, 1f), SPRING_FLOAT_MEDIUM, label = "folderBigAlpha")
    val smallAlpha by animateFloatAsState((hdrProgress * 2f).coerceIn(0f, 1f), SPRING_FLOAT_MEDIUM, label = "folderSmallAlpha")
    val hdrAlpha by animateFloatAsState(hdrProgress, SPRING_FLOAT_MEDIUM, label = "folderHdrAlpha")
    val shadowAlpha by animateFloatAsState((1f - artProgress * 1.5f).coerceIn(0f, 1f), SPRING_FLOAT_MEDIUM, label = "folderShadowAlpha")

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background)
            .nestedScroll(elasticNestedScroll)
            .graphicsLayer { translationY = overscrollPx }
    ) {
        LazyColumn(
            state = listState,
            modifier = Modifier.fillMaxSize(),
            contentPadding = PaddingValues(
                top = HEADER_HEIGHT + ART_EXPANDED + 12.dp,
                bottom = 32.dp
            )
        ) {
            item(key = "folder_header_info") {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 20.dp)
                        .padding(top = 16.dp, bottom = 4.dp)
                        .alpha(bigAlpha)
                ) {
                    Text(
                        text = folderName,
                        style = MaterialTheme.typography.titleLarge,
                        color = MaterialTheme.colorScheme.onBackground,
                        fontWeight = FontWeight.Bold,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis
                    )
                    Spacer(Modifier.height(4.dp))
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = Icons.Default.Folder,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.onSurfaceVariant,
                            modifier = Modifier.size(20.dp)
                        )
                        Spacer(Modifier.width(8.dp))
                        Text(
                            text = folderPath,
                            style = MaterialTheme.typography.labelLarge,
                            color = MaterialTheme.colorScheme.onBackground,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                    Spacer(Modifier.height(4.dp))
                    Text(
                        text = playlistMeta,
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
            }

            item(key = "folder_action_buttons") {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 20.dp, vertical = 12.dp)
                        .alpha(1f - stickyAlpha)
                        .onGloballyPositioned { coords ->
                            actionBarYPx = coords.positionInRoot().y
                        },
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    IconButton(onClick = { }) {
                        Icon(
                            imageVector = Icons.Default.MoreHoriz,
                            contentDescription = "Más opciones",
                            tint = MaterialTheme.colorScheme.onBackground
                        )
                    }
                    IconButton(onClick = { viewModel.toggleFavoriteFolder(folderPath) }) {
                        Icon(
                            imageVector = if (isFavoriteFolder) Icons.Default.CheckCircle else Icons.Default.AddCircleOutline,
                            contentDescription = "Fijar carpeta",
                            tint = if (isFavoriteFolder) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onBackground
                        )
                    }

                    Spacer(Modifier.weight(1f))

                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Row(
                            modifier = Modifier
                                .clip(RoundedCornerShape(50))
                                .background(actionColor.copy(alpha = 0.15f))
                                .clickable(enabled = songs.isNotEmpty()) { onPlayCollection(songs, true) }
                                .padding(horizontal = 16.dp, vertical = 16.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.Center
                        ) {
                            Icon(
                                imageVector = Icons.Default.Shuffle,
                                contentDescription = null,
                                tint = actionColor,
                                modifier = Modifier.size(18.dp)
                            )
                            Spacer(Modifier.width(8.dp))
                            Text(
                                text = "Aleatorio",
                                color = actionColor,
                                fontWeight = FontWeight.Bold,
                                style = MaterialTheme.typography.bodyMedium
                            )
                        }

                        Spacer(Modifier.width(10.dp))

                        @OptIn(ExperimentalMaterial3ExpressiveApi::class)
                        val cookieShape = MaterialShapes.Cookie6Sided.toShape()

                        FloatingActionButton(
                            onClick = { if (songs.isNotEmpty()) onPlayCollection(songs, false) },
                            shape = cookieShape,
                            containerColor = MaterialTheme.colorScheme.primary,
                            contentColor = MaterialTheme.colorScheme.onPrimary
                        ) {
                            Icon(
                                imageVector = Icons.Default.PlayArrow,
                                contentDescription = "Reproducir"
                            )
                        }
                    }
                }
            }

            if (songs.isEmpty()) {
                item(key = "folder_empty") {
                    Text(
                        text = "Esta carpeta no contiene canciones",
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        modifier = Modifier.padding(horizontal = 20.dp, vertical = 12.dp)
                    )
                }
            } else {
                itemsIndexed(
                    items = songs,
                    key = { _, song -> song.id },
                    contentType = { _, _ -> "folder_song" }
                ) { index, song ->
                    val cancion = remember(song.id, song.title, song.artist, song.albumId) {
                        Cancion(
                            caratulaUri = libraryViewModel.getAlbumArtUri(song.albumId),
                            titulo = song.title,
                            artista = song.artist
                        )
                    }
                    ItemCancionAlbum(
                        cancion = cancion,
                        trackNumber = index + 1,
                        onClick = { onPlaySong(song, songs) },
                        menuContent = {
                            SongOverflowMenuButton(
                                song = song,
                                source = SongMenuSource.Library,
                                userPlaylists = userPlaylists,
                                playlistIdsContainingSong = playlistMembershipBySong[song.id].orEmpty(),
                                isFavorite = song.id in favoriteSongIds,
                                onPlayNext = { playbackViewModel.playNext(song) },
                                onAddToQueue = { playbackViewModel.addToQueue(song) },
                                onOpenAlbum = onAlbumClick,
                                onOpenArtist = onArtistClick,
                                onAddToPlaylist = { playlistId ->
                                    libraryViewModel.addSongToPlaylist(playlistId, song.id)
                                },
                                onAddToFavorites = {
                                    libraryViewModel.toggleSongFavorite(song.id)
                                },
                                onDeleteSong = {}
                            )
                        }
                    )
                }
            }
        }

        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(HEADER_HEIGHT)
                .align(Alignment.TopCenter)
                .background(MaterialTheme.colorScheme.background.copy(alpha = hdrAlpha))
                .padding(horizontal = 4.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = onBack) {
                Icon(
                    imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                    contentDescription = "Volver",
                    tint = MaterialTheme.colorScheme.onBackground
                )
            }
            Spacer(Modifier.width(60.dp))
            Column(
                modifier = Modifier
                    .weight(1f)
                    .alpha(smallAlpha)
            ) {
                Text(
                    text = folderName,
                    style = MaterialTheme.typography.titleMedium,
                    color = MaterialTheme.colorScheme.onBackground,
                    fontWeight = FontWeight.Bold,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
                Text(
                    text = folderPath,
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
        }

        val effectiveShadowAlpha = shadowAlpha * 0.8f
        val shadowModifier = remember(dominantColor, effectiveShadowAlpha, hasColor) {
            if (hasColor && effectiveShadowAlpha > 0.01f) {
                Modifier.coloredShadow(
                    color = dominantColor,
                    borderRadius = 16.dp,
                    blurRadius = 28.dp,
                    offsetY = 11.dp,
                    shadowAlpha = effectiveShadowAlpha
                )
            } else Modifier
        }

        Box(
            modifier = Modifier
                .padding(start = artStart, top = artTop)
                .size(artSize)
                .then(shadowModifier)
                .clip(RoundedCornerShape(cornerRad))
                .background(MaterialTheme.colorScheme.surfaceVariant),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = Icons.Default.Folder,
                contentDescription = "Carpeta",
                modifier = Modifier.size(artSize * 0.5f),
                tint = MaterialTheme.colorScheme.onSurfaceVariant
            )
        }

        if (isSticky) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = HEADER_HEIGHT)
                    .background(
                        brush = Brush.verticalGradient(
                            colors = listOf(
                                MaterialTheme.colorScheme.background,
                                MaterialTheme.colorScheme.background.copy(alpha = 0f)
                            ),
                            startY = 0f,
                            endY = with(density) { 80.dp.toPx() }
                        )
                    )
                    .padding(horizontal = 20.dp, vertical = 12.dp)
                    .align(Alignment.TopCenter),
                verticalAlignment = Alignment.CenterVertically
            ) {
                IconButton(onClick = { }) {
                    Icon(
                        imageVector = Icons.Default.MoreHoriz,
                        contentDescription = "Más opciones",
                        tint = MaterialTheme.colorScheme.onBackground
                    )
                }
                IconButton(onClick = { viewModel.toggleFavoriteFolder(folderPath) }) {
                    Icon(
                        imageVector = if (isFavoriteFolder) Icons.Default.CheckCircle else Icons.Default.AddCircleOutline,
                        contentDescription = "Fijar carpeta",
                        tint = if (isFavoriteFolder) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onBackground
                    )
                }

                Spacer(Modifier.weight(1f))

                Row(verticalAlignment = Alignment.CenterVertically) {
                    Row(
                        modifier = Modifier
                            .clip(RoundedCornerShape(50))
                            .background(actionColor.copy(alpha = 0.15f))
                            .clickable(enabled = songs.isNotEmpty()) { onPlayCollection(songs, true) }
                            .padding(horizontal = 16.dp, vertical = 16.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.Shuffle,
                            contentDescription = null,
                            tint = actionColor,
                            modifier = Modifier.size(18.dp)
                        )
                        Spacer(Modifier.width(8.dp))
                        Text(
                            text = "Aleatorio",
                            color = actionColor,
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.bodyMedium
                        )
                    }

                    Spacer(Modifier.width(10.dp))

                    @OptIn(ExperimentalMaterial3ExpressiveApi::class)
                    val cookieShape = MaterialShapes.Cookie6Sided.toShape()

                    FloatingActionButton(
                        onClick = { if (songs.isNotEmpty()) onPlayCollection(songs, false) },
                        shape = cookieShape,
                        containerColor = MaterialTheme.colorScheme.primary,
                        contentColor = MaterialTheme.colorScheme.onPrimary
                    ) {
                        Icon(
                            imageVector = Icons.Default.PlayArrow,
                            contentDescription = "Reproducir"
                        )
                    }
                }
            }
        }
    }
}
